function ForgeTuyereCoolerMaker.init() ForgeTuyereCoolerMaker.ironStock=16; ForgeTuyereCoolerMaker.bronzeStock=12; ForgeTuyereCoolerMaker.woodStock=12; ForgeTuyereCoolerMaker.leatherStock=8; ForgeTuyereCoolerMaker.silverStock=8; ForgeTuyereCoolerMaker.goldStock=6; ForgeTuyereCoolerMaker.jewelStock=4; ForgeTuyereCoolerMaker.pearlStock=4; ForgeTuyereCoolerMaker.productStock={}; ForgeTuyereCoolerMaker.buildings={}; ForgeTuyereCoolerMaker.maker=nil; ForgeTuyereCoolerMaker.activeMaking={}; ForgeTuyereCoolerMaker.totalProducts=0; ForgeTuyereCoolerMaker.dayTimer=0; print("[ForgeTuyereCoolerMaker] Royal Forge Tuyere Cooler Maker System initialized (6 products, 4 buildings)") end
function ForgeTuyereCoolerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeTuyereCoolerMaker.maker={name=n or ("Hladilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Hladilnik najet: %s (spretnost: %d)",ForgeTuyereCoolerMaker.maker.name,s),"success") end; return true end
function ForgeTuyereCoolerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeTuyereCoolerMaker.build(id) local ok,e=ForgeTuyereCoolerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeTuyereCoolerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeTuyereCoolerMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeTuyereCoolerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeTuyereCoolerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeTuyereCoolerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeTuyereCoolerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeTuyereCoolerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeTuyereCoolerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeTuyereCoolerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeTuyereCoolerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeTuyereCoolerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeTuyereCoolerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeTuyereCoolerMaker.buildings==0 then return false,"Potrebna hladilna delavnica" end; if not ForgeTuyereCoolerMaker.maker then return false,"Potreben hladilnik" end; return true end
function ForgeTuyereCoolerMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeTuyereCoolerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeTuyereCoolerMaker.ironStock=ForgeTuyereCoolerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeTuyereCoolerMaker.bronzeStock=ForgeTuyereCoolerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeTuyereCoolerMaker.woodStock=ForgeTuyereCoolerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeTuyereCoolerMaker.leatherStock=ForgeTuyereCoolerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeTuyereCoolerMaker.silverStock=ForgeTuyereCoolerMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeTuyereCoolerMaker.goldStock=ForgeTuyereCoolerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeTuyereCoolerMaker.jewelStock=ForgeTuyereCoolerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeTuyereCoolerMaker.pearlStock=ForgeTuyereCoolerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeTuyereCoolerMaker.maker then t=math.max(1,t-math.floor(ForgeTuyereCoolerMaker.maker.skill/13)) end; table.insert(ForgeTuyereCoolerMaker.activeMaking,{id="forgetuyerecooler_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeTuyereCoolerMaker.completeMaking(m) local q=1.0+(ForgeTuyereCoolerMaker.getQualityBonus()/100); if ForgeTuyereCoolerMaker.maker then q=q+(ForgeTuyereCoolerMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeTuyereCoolerMaker.productStock[m.productType]=(ForgeTuyereCoolerMaker.productStock[m.productType] or 0)+m.quantity; ForgeTuyereCoolerMaker.totalProducts=ForgeTuyereCoolerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeTuyereCoolerMaker.maker then ForgeTuyereCoolerMaker.maker.itemsMade=ForgeTuyereCoolerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeTuyereCoolerMaker.maker.skill=math.min(100,ForgeTuyereCoolerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Hladilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgetuyerecooler.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeTuyereCoolerMaker.update(dt) if not _G.state then return end; ForgeTuyereCoolerMaker.dayTimer=ForgeTuyereCoolerMaker.dayTimer+dt; if ForgeTuyereCoolerMaker.dayTimer>=30 then ForgeTuyereCoolerMaker.dayTimer=0; for i=#ForgeTuyereCoolerMaker.activeMaking,1,-1 do local m=ForgeTuyereCoolerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeTuyereCoolerMaker.completeMaking(m); table.remove(ForgeTuyereCoolerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeTuyereCoolerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeTuyereCoolerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
